import { RoomGame } from '../room-game.enum';

export default interface RoomCreateRequest {
    playerName: string;
    /** The name of the room, without the tag the API adds to it (ROOM_TAG_SEPARATOR) */
    roomName: string;
    maxPlayer: number;
    game: RoomGame;
    /** Makes the room private: a player joins it with this password. The API keeps a hash of it */
    password?: string;
    /** A secret of the host, generated by its page: the API keeps its hash, to let the host reconnect the room */
    token: string;
    /**
     * A random id of the browser, kept in its local storage and shared by its tabs: the API keeps its hash, to refuse the
     * joins of a browser the host removed from the room whatever its name. Never sent to the other players
     */
    browserId: string;
}
